// grid.reach (#556; canvas primitives: Check input: `grid.reach`): every floor a game's runs generated can be finished,
// and a flow field leads every spawn to its target. It reads the runs of the playtest it names, each bot's run i at
// hash(the playtest's seed, i), played as the playtest plays it, so it checks the floors the piece really generated by
// run seed, never floors the agent picked. The replica records the interface's grid only at the steps it changes
// (deep-logic's play `changes`), and a floor is the grid at each step `ready` turns true; with no `ready`, at step 0 and
// at each step `floor` changes. Over each floor it runs its own breadth-first search, never the piece's: from each
// start over open, door, key and exit cells, 4 or 8 neighbours on a square grid and 6 on a hex grid with its offset
// (the first-party bots' and the drawn board's convention), within a layer, and through the grid's links; a locked
// cell opens once the search has reached a cell holding its key under `locks`, every key kept, and the search runs on
// until nothing more opens. Every goal and every cell of an `every` class must be reached, or it fails grid.unreached;
// a depth `depths` lists that no run generated is BLOCKED, never PASS. The flow form reads `next` and `cost` at each
// step they change: at every step but the `lag` steps after one at which the grid changed (step 0 is no change), every
// cell its own search leads to a target must step to a neighbour that isn't solid and whose cost is lower, and every
// spawn must reach a target both by its own search and by following `next`, or it fails grid.flow.
import { createHash } from 'node:crypto';
import type { CheckResult, Failure } from '@deepbuild/conformance';
import { lower, refusal } from './bots.ts';
import { declared, goalTest, linksOf, lockRefusal, type Name, type PlayIface } from './iface.ts';
import { ended, failure, runSeed, said } from './run.ts';
import type { Play, PlayAnswer, PlaytestInput } from './types.ts';

/** A cell as the interface names one: x, and y running on through the layers (layer × height + row). */
export type Cell = [number, number];
/** A goal, a target or a spawn: a cell, or every cell of a class. */
export type Place = Cell | string;
/** The flow form's input. */
export interface FlowInput { next: string; cost: string; solid?: string[]; targets: Place[]; spawns: Place[]; lag?: number }
/** grid.reach's own input: the playtest it names, then the search's or the flow form's. */
export interface ReachInput { playtest: string; starts?: Cell[]; goals?: Place[]; every?: string[]; depths?: number[]; flow?: FlowInput }

/** A floor the search judged: its run, seed, depth and step, its cells' hash, and what it left unreached. */
export interface FloorFound { run: string; seed: number; depth: number; step: number; hash: string; reached: boolean; unreached: Cell[]; nearest: Cell | null }
/** A flow form failure. */
export interface FlowFound { run: string; step: number; cell: Cell; why: 'rises' | 'solid' | 'loops' | 'unreached' }
/**
 * What grid.reach found, beside check.kind@1's result: every floor, the runs that generated each depth, the distinct
 * floors at each depth by hash, the flow form's failures, and the time its searches took.
 */
export interface ReachFound { floors: FloorFound[]; coverage: Record<string, number>; distinct: Record<string, number>; flow: FlowFound[]; search_ms: number }

// ---- The grid and the search.

const CLASSES = ['open', 'blocked', 'door', 'locked', 'key', 'exit'] as const;
const PASSABLE = new Set(['open', 'door', 'key', 'exit']);

/** The grid as the interface declares it: what the search reads. */
export interface Shape { w: number; h: number; layers: number; hex: { pointy: boolean; odd: boolean } | null; eight: boolean; classes: [string, Set<number>][]; locks: Map<number, number> }

function shapeOf(play: PlayIface): Shape {
  const g = play.grid!;
  const classes = (g['classes'] ?? {}) as Record<string, number[]>;
  const hex = g['hex'] as { orient?: string; offset?: string } | undefined;
  return {
    w: g.size[0], h: g.size[1], layers: Number(g['layers'] ?? 1) || 1,
    hex: g['shape'] === 'hex' ? { pointy: hex?.orient !== 'flat', odd: hex?.offset !== 'even' } : null,
    eight: g['moves'] === 8,
    classes: CLASSES.flatMap((c) => (Array.isArray(classes[c]) ? [[c, new Set(classes[c]!.map(Number))] as [string, Set<number>]] : [])),
    locks: new Map(Object.entries((g['locks'] ?? {}) as Record<string, number>).map(([k, v]) => [Number(k), Number(v)])),
  };
}

/** A value's class: the first class whose values hold it; a value no class holds counts as blocked. */
function classOf(s: Shape, v: number): string {
  return s.classes.find(([, vs]) => vs.has(v))?.[0] ?? 'blocked';
}

const FOUR: Cell[] = [[0, -1], [1, 0], [0, 1], [-1, 0]];
const EIGHT: Cell[] = [...FOUR, [1, -1], [1, 1], [-1, 1], [-1, -1]];

/**
 * Cell i's neighbours on its own layer: 4 or 8 on a square grid, 6 on a hex grid. On a hex grid the shifted rows
 * (pointy) or columns (flat) are the odd ones with offset odd and the even ones with offset even, as the drawn board
 * (Mark set: hex grid) and the first-party bots lay them out. `parity` flips that, for the kit's planted runner.
 */
function neighbours(s: Shape, i: number, parity = false): number[] {
  const x = i % s.w;
  const layer = Math.floor(i / (s.w * s.h));
  const y = Math.floor(i / s.w) - layer * s.h;
  let steps: Cell[];
  if (!s.hex) steps = s.eight ? EIGHT : FOUR;
  else {
    const line = s.hex.pointy ? y : x;
    const sh = (((line % 2) + 2) % 2 === 1) === (s.hex.odd !== parity) ? 1 : 0;
    steps = s.hex.pointy
      ? [[1, 0], [sh, -1], [sh - 1, -1], [-1, 0], [sh - 1, 1], [sh, 1]]
      : [[1, sh - 1], [0, -1], [-1, sh - 1], [-1, sh], [0, 1], [1, sh]];
  }
  const out: number[] = [];
  for (const [dx, dy] of steps) {
    const nx = x + dx;
    const ny = y + dy;
    if (nx >= 0 && nx < s.w && ny >= 0 && ny < s.h) out.push((layer * s.h + ny) * s.w + nx);
  }
  return out;
}

/**
 * A runner: the plug-in's own search, or a planted one the kit must catch (#68): its neighbours, and whether a locked
 * cell opens with the keys the search holds.
 */
export interface Runner { neighbours(s: Shape, i: number): number[]; opens(s: Shape, locked: number, keys: Set<number>): boolean }

/** The plug-in's own runner. */
export const OWN: Runner = {
  neighbours: (s, i) => neighbours(s, i),
  opens: (s, locked, keys) => { const k = s.locks.get(locked); return k !== undefined && keys.has(k); },
};

/** The kit's planted runners, each wrong in one way a fixture must catch. */
export const PLANTED: Record<string, Runner> = {
  // Takes a hex grid's neighbours by the other offset.
  'offset-even': { neighbours: (s, i) => neighbours(s, i, true), opens: OWN.opens },
  // Treats the cells stacked above and below on the other layers as neighbours.
  'stacked-layers': {
    neighbours: (s, i) => {
      const plane = s.w * s.h;
      const out = neighbours(s, i);
      for (const j of [i - plane, i + plane]) if (j >= 0 && j < plane * s.layers) out.push(j);
      return out;
    },
    opens: OWN.opens,
  },
  // Opens every lock, its key reached or not.
  'opens-locks': { neighbours: OWN.neighbours, opens: () => true },
};

/** The cells the search reaches from `starts`, with key-and-door closure; `links` are (from, to, two_way). */
function search(s: Shape, cells: ArrayLike<number>, links: [number, number, boolean][], starts: number[], r: Runner = OWN): Uint8Array {
  const n = s.w * s.h * s.layers;
  const reached = new Uint8Array(n);
  const keyValues = new Set(s.locks.values());
  const held = new Set<number>();
  // A locked cell next to a reached one, by the key value it waits on.
  const waiting = new Map<number, number[]>();
  const linked = new Map<number, number[]>();
  const join = (m: Map<number, number[]>, k: number, v: number): void => { const l = m.get(k); if (l) l.push(v); else m.set(k, [v]); };
  for (const [f, t, two] of links) {
    if (!(f >= 0 && f < n && t >= 0 && t < n)) continue;
    join(linked, f, t);
    if (two) join(linked, t, f);
  }
  const queue: number[] = [];
  const reach = (i: number): void => {
    if (reached[i]) return;
    reached[i] = 1;
    queue.push(i);
    const v = cells[i]!;
    if (keyValues.has(v) && !held.has(v)) {
      held.add(v);
      for (const m of waiting.get(v) ?? []) reach(m);
      waiting.delete(v);
    }
  };
  const enter = (m: number): void => {
    if (reached[m]) return;
    const c = classOf(s, cells[m]!);
    if (c === 'locked') {
      if (r.opens(s, cells[m]!, held)) reach(m);
      else { const k = s.locks.get(cells[m]!); if (k !== undefined) join(waiting, k, m); }
    } else if (PASSABLE.has(c)) reach(m);
  };
  for (const st of starts) if (st >= 0 && st < n) reach(st);
  for (let q = 0; q < queue.length; q++) {
    const i = queue[q]!;
    for (const m of r.neighbours(s, i)) enter(m);
    for (const m of linked.get(i) ?? []) enter(m);
  }
  return reached;
}

/** Cell i as the interface names it. */
const cellOf = (s: Shape, i: number): Cell => [i % s.w, Math.floor(i / s.w)];
/** A cell's index, or -1 off the grid. */
const indexOf = (s: Shape, [x, y]: Cell): number => (x >= 0 && x < s.w && y >= 0 && y < s.h * s.layers ? y * s.w + x : -1);

/** The reached cell nearest cell t: the fewest |dx| + |dy|, y running on through the layers, ties to the first. */
function nearest(s: Shape, reached: Uint8Array, t: number): number | null {
  const [tx, ty] = cellOf(s, t);
  let best: number | null = null;
  let least = Infinity;
  for (let i = 0; i < reached.length; i++) {
    if (!reached[i]) continue;
    const [x, y] = cellOf(s, i);
    const d = Math.abs(x - tx) + Math.abs(y - ty);
    if (d < least) { best = i; least = d; }
  }
  return best;
}

/**
 * The cells a list of places names, in its order, without repeats: a cell, or every cell holding a value of a class
 * in row-major order.
 */
function placesOf(s: Shape, cells: ArrayLike<number>, list: Place[]): number[] {
  const out: number[] = [];
  for (const p of list) {
    if (typeof p === 'string') { for (let i = 0; i < cells.length; i++) if (classOf(s, cells[i]!) === p) out.push(i); }
    else { const i = indexOf(s, p); if (i >= 0) out.push(i); }
  }
  return [...new Set(out)];
}

// ---- A run's floors, from what the replica recorded at the steps each array changed.

type Changes = { step: number; value: unknown }[];
/** The value a recorded array held at step k: the last change at or before it. */
function at(changes: Changes | undefined, k: number): unknown {
  let v: unknown;
  for (const c of changes ?? []) { if (c.step > k) break; v = c.value; }
  return v;
}
const ints = (v: unknown): number[] => (Array.isArray(v) ? v.map(Number) : v === undefined || v === null ? [] : [Number(v)]);
const pathOf = (n: Name): string => (typeof n === 'string' ? n : n.name);

/** A declared name's array path, by the name an expression or the brief uses, or the path itself. */
function resolveName(play: PlayIface, name: string): string {
  const d = declared(play).find((x) => x.name === name);
  return d ? pathOf(d.at) : name;
}

/** What a run's floors need recorded: the grid, the floor, the self unit's cell and the links, at each change. */
function watched(play: PlayIface, flow: FlowInput | undefined): { cells: string; floor?: string; unit?: string; links?: { rows: string; count: string }; next?: string; cost?: string } {
  const g = play.grid!;
  const links = linksOf(play);
  return {
    cells: pathOf(g.cells),
    ...(g.floor !== undefined ? { floor: pathOf(g.floor) } : {}),
    ...(play.units?.cell !== undefined ? { unit: pathOf(play.units.cell) } : {}),
    ...(links ? { links: { rows: links.rows, count: links.count } } : {}),
    ...(flow ? { next: resolveName(play, flow.next), cost: resolveName(play, flow.cost) } : {}),
  };
}

/** `ready` as the play interface gives it, an expression over its names read as a goal's is, or none. */
function readyOf(play: PlayIface): ReturnType<typeof goalTest> | undefined {
  const text = play.grid?.['ready'];
  return typeof text === 'string' && text.trim() ? goalTest(text, play) : undefined;
}

/** The steps a run's floors were recorded at: where `ready` turns true; with no `ready`, step 0 and each step `floor` changes. */
function floorSteps(answer: PlayAnswer, w: ReturnType<typeof watched>, ready: ReturnType<typeof readyOf>): number[] {
  if (ready) {
    const out: number[] = [];
    let before = false;
    for (let k = 0; k < answer.steps; k++) {
      const now = ready.at(answer.values, k);
      if (now && !before) out.push(k);
      before = now;
    }
    return out;
  }
  if (!w.floor) return answer.steps > 0 ? [0] : [];
  const out = [0];
  let last = JSON.stringify(at(answer.changes?.[w.floor], 0));
  for (const c of answer.changes?.[w.floor] ?? []) {
    const v = JSON.stringify(c.value);
    if (c.step > 0 && v !== last) out.push(c.step);
    last = v;
  }
  return out.filter((k) => k < answer.steps);
}

/** A run's links at step k, as (from, to, two_way). */
function linksAt(answer: PlayAnswer, w: ReturnType<typeof watched>, k: number): [number, number, boolean][] {
  if (!w.links) return [];
  const flat = ints(at(answer.changes?.[w.links.rows], k));
  const n = Math.max(0, ints(at(answer.changes?.[w.links.count], k))[0] ?? 0);
  const out: [number, number, boolean][] = [];
  for (let r = 0; r < n && 3 * r + 2 < flat.length; r++) out.push([flat[3 * r]!, flat[3 * r + 1]!, flat[3 * r + 2]! !== 0]);
  return out;
}

/** The sha256 of a floor's cells, as i32 little-endian. */
function floorHash(cells: number[]): string {
  const b = Buffer.alloc(4 * cells.length);
  cells.forEach((v, i) => b.writeInt32LE(v | 0, 4 * i));
  return createHash('sha256').update(b).digest('hex');
}

const cellText = (s: Shape, i: number): string => `[${cellOf(s, i).join(', ')}]`;

/**
 * One floor judged: every goal and every cell of an `every` class reached, from the starts. The unreached cells are in
 * the order a failure names the first: each goal as `goals` lists them, then each cell of an `every` class.
 */
function judgeFloor(s: Shape, cells: number[], links: [number, number, boolean][], starts: number[], input: ReachInput, r: Runner = OWN): { unreached: number[]; nearest: number | null; reached: Uint8Array } {
  const reached = search(s, cells, links, starts, r);
  const want = [...new Set([...placesOf(s, cells, input.goals ?? ['exit']), ...placesOf(s, cells, input.every ?? [])])];
  const unreached = want.filter((i) => !reached[i]);
  return { unreached, nearest: unreached.length ? nearest(s, reached, unreached[0]!) : null, reached };
}

/**
 * The flow form over one run: at each step but the `lag` steps after a step the grid changed (step 0 is no change),
 * every cell its own search leads to a target steps to a neighbour that isn't solid and whose cost is lower, and every
 * spawn reaches a target by its own search and by following `next`. Answers the first failure, or none. A state the
 * arrays hold unchanged is judged once, at the first step the lag allows.
 */
function judgeFlow(s: Shape, answer: PlayAnswer, w: ReturnType<typeof watched>, flow: FlowInput, r: Runner = OWN): { step: number; cell: number; why: FlowFound['why'] } | undefined {
  const lag = flow.lag ?? 0;
  const solid = new Set(flow.solid ?? ['blocked']);
  const marks = new Set<number>([0]);
  for (const p of [w.cells, w.next!, w.cost!, ...(w.links ? [w.links.rows, w.links.count] : [])]) for (const c of answer.changes?.[p] ?? []) marks.add(c.step);
  const gridChanges = (answer.changes?.[w.cells] ?? []).map((c) => c.step).filter((k) => k > 0);
  const points = [...marks].filter((k) => k < answer.steps).sort((a, b) => a - b);
  for (let j = 0; j < points.length; j++) {
    const from = points[j]!;
    const until = points[j + 1] ?? answer.steps;
    const changed = gridChanges.filter((k) => k <= from).at(-1);
    const k = changed === undefined ? from : Math.max(from, changed + lag);
    if (k >= until) continue;
    const cells = ints(at(answer.changes?.[w.cells], k));
    const next = ints(at(answer.changes?.[w.next!], k));
    const cost = ints(at(answer.changes?.[w.cost!], k));
    const found = flowAt(s, cells, next, cost, linksAt(answer, w, k), flow, solid, r);
    if (found) return { step: k, ...found };
  }
  return undefined;
}

/** The flow form's judgement of one state, or none when it holds. */
function flowAt(s: Shape, cells: number[], next: number[], cost: number[], links: [number, number, boolean][], flow: FlowInput, solid: Set<string>, r: Runner = OWN): { cell: number; why: FlowFound['why'] } | undefined {
  const n = s.w * s.h * s.layers;
  const isSolid = (i: number): boolean => solid.has(classOf(s, cells[i]!));
  const targets = new Set(placesOf(s, cells, flow.targets).filter((i) => !isSolid(i)));
  // One step from cell i, and the cells one step leads from to i: a grid's steps are their own reverse; a link isn't.
  const step = (i: number): number[] => {
    const out = r.neighbours(s, i);
    for (const [f, t, two] of links) { if (f === i) out.push(t); else if (two && t === i) out.push(f); }
    return out;
  };
  const back = (i: number): number[] => {
    const out = r.neighbours(s, i);
    for (const [f, t, two] of links) { if (t === i) out.push(f); else if (two && f === i) out.push(t); }
    return out;
  };
  // The cells a target can be reached from by the search's own steps over cells that aren't solid.
  const leads = new Uint8Array(n);
  const queue = [...targets];
  for (const t of queue) leads[t] = 1;
  for (let q = 0; q < queue.length; q++) {
    for (const m of back(queue[q]!)) if (!leads[m] && !isSolid(m)) { leads[m] = 1; queue.push(m); }
  }
  for (let i = 0; i < n; i++) {
    if (!leads[i] || targets.has(i)) continue;
    const to = next[i] ?? -1;
    if (to < 0 || to >= n || !step(i).includes(to)) return { cell: i, why: 'unreached' };
    if (isSolid(to)) return { cell: i, why: 'solid' };
    if (!((cost[to] ?? Infinity) < (cost[i] ?? -Infinity))) return { cell: i, why: 'rises' };
  }
  for (const sp of placesOf(s, cells, flow.spawns)) {
    if (!leads[sp]) return { cell: sp, why: 'unreached' };
    const seen = new Set<number>();
    for (let i = sp; !targets.has(i); i = next[i]!) {
      if (seen.has(i)) return { cell: sp, why: 'loops' };
      seen.add(i);
      const to = next[i] ?? -1;
      if (to < 0 || to >= n) return { cell: sp, why: 'unreached' };
    }
  }
  return undefined;
}

// ---- The check.

/** Runs played at once: a playtest's replicas are leased two at a time. */
const AT_ONCE = 2;

/**
 * grid.reach over the runs of the playtest whose input is `input`: each bot's run i at hash(the playtest's seed, i),
 * played as the playtest plays it with the grid recorded at each change, then each floor searched. testsRun counts the
 * runs it read. `runner` is the plug-in's own search, or the kit's planted one.
 */
export async function runReach(reach: ReachInput, input: PlaytestInput, play: Play, runner: Runner = OWN): Promise<CheckResult & { reach: ReachFound }> {
  const found: ReachFound = { floors: [], coverage: {}, distinct: {}, flow: [], search_ms: 0 };
  const stop = (f: Failure): CheckResult & { reach: ReachFound } => ({ ...ended([f]), reach: found });
  const iface = input.play;
  if (!iface) return stop(failure('grid.reach', 'refused before any run: grid.reach reads the play interface of the playtest it names, and its input gives none', false));
  const locked = lockRefusal(iface);
  if (locked) return stop(failure('play', `refused before any run: ${locked}`, false));
  if (!iface.grid) return stop(failure('play', 'play.missing: grid: grid.reach reads the play interface\'s grid form, and it declares none', false));
  let ready: ReturnType<typeof readyOf>;
  try { ready = readyOf(iface); } catch (e) { return stop(failure('play', `refused before any run: ready: ${(e as Error).message}`, false)); }
  const s = shapeOf(iface);
  const w = watched(iface, reach.flow);
  // The interface taken by the piece before any run (play.missing names the name), then each bot.
  try {
    await play(input.piece, { seed: input.seed, span: { steps: 0 }, play: iface, values: [], frames: [] });
  } catch (e) {
    const why = said(e);
    return stop(failure('play', why.startsWith('play.missing') ? why : `refused before any run: ${why}`, false));
  }
  for (const [b, bot] of input.bots.entries()) {
    const why = refusal(bot, iface);
    if (why) return stop(failure(`bot ${b}`, `refused before any run: ${why}`, false));
  }
  const common = { span: input.span ?? 120, play: iface, ...(input.piece_seed ? { piece_seed: input.piece_seed } : {}) };
  const changes = [w.cells, w.floor, w.unit, w.links?.rows, w.links?.count, w.next, w.cost].filter((p): p is string => typeof p === 'string');
  const runs = input.runs ?? 20;
  const jobs = input.bots.flatMap((bot, b) => Array.from({ length: runs }, (_, i) => ({ bot, n: b * runs + i, test: `bot ${b} run ${i}`, seed: runSeed(input.seed, i) })));
  const done: { test: string; n: number; seed: number; track: string; answer: PlayAnswer }[] = [];
  let refused: Failure | undefined;
  const next = async (): Promise<void> => {
    for (let job = jobs.shift(); job && !refused; job = jobs.shift()) {
      try {
        const answer = await play(input.piece, { ...common, seed: job.seed, bot: lower(job.bot), values: ready?.reads ?? [], changes: [...new Set(changes)], frames: [] });
        done.push({ test: job.test, n: job.n, seed: job.seed, track: answer.track, answer });
      } catch (e) {
        refused = failure(job.test, `refused: ${said(e)}`, false);
      }
    }
  };
  await Promise.all(Array.from({ length: AT_ONCE }, next));
  done.sort((a, b) => a.n - b.n);
  const evidence = done.map((d) => d.track);
  if (refused) return { ...ended([refused], evidence, done.length), reach: found };
  const failures: Failure[] = [];
  const blocked: [number, string][] = [];
  if (reach.flow) {
    for (const d of done) {
      const f = judgeFlow(s, d.answer, w, reach.flow, runner);
      if (!f) continue;
      const cell = cellOf(s, f.cell);
      found.flow.push({ run: d.test, step: f.step, cell, why: f.why });
      failures.push(failure(d.test, `grid.flow: ${d.test} (seed ${d.seed}): at step ${f.step}, the cell ${cellText(s, f.cell)} ${f.why === 'rises' ? 'steps to a neighbour whose cost isn\'t lower' : f.why === 'solid' ? 'steps into a solid cell' : f.why === 'loops' ? 'follows next round a loop' : 'reaches no target'} (${f.why})`));
    }
  } else {
    // Every floor a run recorded is searched; `depths` names those that must have been generated.
    const seen = new Map<number, Set<string>>();
    const hashes = new Map<number, Set<string>>();
    const me = iface.units?.self ?? 0;
    for (const d of done) {
      for (const k of floorSteps(d.answer, w, ready)) {
        const cells = ints(at(d.answer.changes?.[w.cells], k));
        // With no `floor`, a run's one floor is depth 1.
        const depth = w.floor ? (ints(at(d.answer.changes?.[w.floor], k))[0] ?? 0) : 1;
        const hash = floorHash(cells);
        (seen.get(depth) ?? seen.set(depth, new Set()).get(depth)!).add(d.test);
        (hashes.get(depth) ?? hashes.set(depth, new Set()).get(depth)!).add(hash);
        const unit = ints(at(d.answer.changes?.[w.unit ?? ''], k));
        const starts = reach.starts ?? (iface['start'] as Cell[] | undefined) ?? (unit.length > 2 * me + 1 ? [[unit[2 * me]!, unit[2 * me + 1]!] as Cell] : []);
        const t0 = performance.now();
        const j = judgeFloor(s, cells, linksAt(d.answer, w, k), starts.map((c) => indexOf(s, c)).filter((i) => i >= 0), reach, runner);
        found.search_ms += performance.now() - t0;
        found.floors.push({ run: d.test, seed: d.seed, depth, step: k, hash, reached: j.unreached.length === 0, unreached: j.unreached.map((i) => cellOf(s, i)), nearest: j.nearest === null ? null : cellOf(s, j.nearest) });
        if (j.unreached.length) {
          const first = j.unreached[0]!;
          const more = j.unreached.length > 1 ? ` (${j.unreached.length - 1} more unreached)` : '';
          failures.push(failure(d.test, `grid.unreached: ${d.test} (seed ${d.seed}), depth ${depth}, step ${k}: cell ${cellText(s, first)}, ${classOf(s, cells[first]!)}, is unreached${more}; nearest ${j.nearest === null ? 'none' : cellText(s, j.nearest)}, the reached cell nearest it`));
        }
      }
    }
    for (const [depth, runs] of [...seen].sort((a, b) => a[0] - b[0])) found.coverage[String(depth)] = runs.size;
    for (const [depth, hs] of [...hashes].sort((a, b) => a[0] - b[0])) found.distinct[String(depth)] = hs.size;
    for (const depth of reach.depths ?? []) if (!seen.has(depth)) { found.coverage[String(depth)] = 0; blocked.push([depth, `BLOCKED: depth ${depth}: 0 runs generated it`]); }
  }
  const unseen = blocked.map(([depth, m]) => failure(`depth ${depth}`, m, false));
  if (failures.length) return { outcome: 'failed', testsRun: done.length, failures: [...failures, ...unseen], evidence, read: [], mask: null, reach: found };
  if (unseen.length) return { outcome: 'missing', testsRun: done.length, failures: unseen, evidence, read: [], mask: null, reach: found };
  return { outcome: 'passed', testsRun: done.length, failures: [], evidence, read: [], mask: null, reach: found };
}
